function uniquePathsWithObstacles(obstacleGrid: number[][]): number {
  const m = obstacleGrid.length;
  const n = obstacleGrid[0].length;
  // Состояние: dp[i][j] — число различных путей из (0, 0) в клетку (i, j)
  const dp: number[][] = Array.from({ length: m }, () => new Array(n).fill(0));

  // Порядок: строки сверху вниз, внутри строки слева направо
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (obstacleGrid[i][j] === 1) {
        // Через препятствие пройти нельзя — путей ноль
        dp[i][j] = 0;
      } else if (i === 0 && j === 0) {
        // База: в свободную стартовую клетку ведёт один путь
        dp[i][j] = 1;
      } else {
        // Переход: пути сверху + пути слева (за границей сетки — 0)
        const up = i > 0 ? dp[i - 1][j] : 0;
        const left = j > 0 ? dp[i][j - 1] : 0;
        dp[i][j] = up + left;
      }
    }
  }

  // Ответ: правый нижний угол
  return dp[m - 1][n - 1];
}

// Время: O(m · n) — каждая клетка один раз
// Память: O(m · n) — полная таблица dp

